    /**
     * Tests getting all QualityChecks.
     *
     * @return    Collection
     */
    public List<QualityCheck> testGetAll() throws Throwable {
    LOGGER.info( "QualityCheckTest:testGetAll() - Retrieving Collection of QualityChecks:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all QualityCheck : " );
    List<QualityCheck> collection  = null;

    try {
        // call the static get method on the QualityCheckService
        collection = service.getAllQualityCheck();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            QualityCheck currEntity  = null;
            Iterator<QualityCheck> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getQualityCheckId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

